import heapq

def match(orders):
    buy_heap = []   # max-heap by price (store -price), then by seq
    sell_heap = []  # min-heap by price, then by seq
    order_book = {}  # id -> dict(side, price, qty, seq, active)
    trades = []
    seq_counter = 0

    def add_to_book(oid):
        info = order_book[oid]
        if info['side'] == 'buy':
            heapq.heappush(buy_heap, (-info['price'], info['seq'], oid))
        else:
            heapq.heappush(sell_heap, (info['price'], info['seq'], oid))

    def top_valid(heap):
        while heap:
            _, _, oid = heap[0]
            info = order_book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return oid
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in order_book:
                order_book[oid]['active'] = False
            continue

        if typ in ('limit', 'ioc'):
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        remaining = qty
        seq = seq_counter
        seq_counter += 1
        order_book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': True}

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0:
            opp_id = top_valid(opp_heap)
            if opp_id is None:
                break
            opp = order_book[opp_id]
            if typ != 'market':
                if side == 'buy' and price < opp['price']:
                    break
                if side == 'sell' and price > opp['price']:
                    break

            trade_qty = min(remaining, opp['qty'])
            trade_price = opp['price']
            if side == 'buy':
                trades.append([oid, opp_id, trade_price, trade_qty])
            else:
                trades.append([opp_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            opp['qty'] -= trade_qty
            order_book[oid]['qty'] = remaining

            if opp['qty'] == 0:
                opp['active'] = False
                heapq.heappop(opp_heap)
            # else opp stays at top with reduced qty; remaining must be 0 now, loop will end

        order_book[oid]['qty'] = remaining

        if typ == 'limit' and remaining > 0:
            add_to_book(oid)
        else:
            order_book[oid]['active'] = False

    return trades

